import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"FD Cal — engineering audit","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/README.html"}],["meta",{"property":"og:title","content":"FD Cal — engineering audit | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/README.html"}],["meta",{"name":"twitter:title","content":"FD Cal — engineering audit | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/README.md","filePath":"audits/README.md","lastUpdated":1794227887000}`),a={name:`audits/README.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="fd-cal-—-engineering-audit" tabindex="-1">FD Cal — engineering audit <a class="header-anchor" href="#fd-cal-—-engineering-audit" aria-label="Permalink to “FD Cal — engineering audit”">​</a></h1><p><strong>Re-audit date:</strong> 9 November 2026<br><strong>Base:</strong> <code>dev</code> at PR #81 squash merge <code>85f2043c4d06ac4f7bcd65ec5aa18452c98ff38a</code><br><strong>Active follow-up branch:</strong> <code>audit/owner-feedback-followups</code><br><strong>Ruleset:</strong> <a href="https://github.com/aaron-fredrick/RULESETS" target="_blank" rel="noreferrer">aaron-fredrick/RULESETS</a></p><p>This audit index has been reconciled against the working branch. Owner decisions and source research are in the <a href="./OWNER-FEEDBACK-RESEARCH.html">owner-feedback research register</a>; implementation evidence and remaining acceptance work are in the <a href="./IMPLEMENTATION-PLAN.html">implementation plan</a>.</p><h2 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to “Reports”">​</a></h2><table tabindex="0"><thead><tr><th>Report</th><th>Coverage</th></tr></thead><tbody><tr><td><a href="./EXECUTIVE-SUMMARY.html">Executive summary</a></td><td>Current finding dispositions, blockers and release readiness</td></tr><tr><td><a href="./IMPLEMENTATION-PLAN.html">Implementation plan</a></td><td>Owner decisions, implementation evidence, acceptance criteria and remaining tasks</td></tr><tr><td><a href="./OWNER-FEEDBACK-RESEARCH.html">Owner-feedback research</a></td><td>Bank product, AIT, transfer-fee, data freshness, search architecture, QA and legal research</td></tr><tr><td><a href="./SEARCH-BUDGET-CALIBRATION.html">Search budget calibration</a></td><td>Controlled 5k/10k/20k/unlimited × 15/30/60s comparison</td></tr><tr><td><a href="./../finance/INTEREST-DAY-COUNT.html">Interest day-count note</a></td><td>Retained start-year 365/366 elapsed-day convention</td></tr><tr><td><a href="./ENGINE-CORE.html">Engine and financial core</a></td><td>Dates, interest, FD cash flows, simulation lifecycle, balances and results</td></tr><tr><td><a href="./STRATEGIES-AND-SEARCH.html">Strategies and search</a></td><td>Greedy, GSS, Absolute R, Absolute R+, search budgets, parity and architecture</td></tr><tr><td><a href="./WEB-UI-UX-ACCESSIBILITY.html">Web UI, UX and accessibility</a></td><td>Form flows, responsive layout, motion, keyboard and screen-reader semantics</td></tr><tr><td><a href="./REPORTING-OUTPUTS.html">Reporting and outputs</a></td><td>In-app metrics, standalone HTML, ledger, charts and financial presentation</td></tr><tr><td><a href="./DATA-AND-FINANCIAL-ASSUMPTIONS.html">Data and financial assumptions</a></td><td>Catalogue quality, provenance, eligibility, fees, AIT and product constraints</td></tr><tr><td><a href="./SECURITY-PRIVACY.html">Security and privacy</a></td><td>Untrusted configuration, DOM rendering, local storage and client-side exposure</td></tr><tr><td><a href="./BUILD-DEPLOYMENT-AND-QUALITY.html">Build, deployment and quality</a></td><td>GitHub Actions, Pages composition, dev preview, tests and operational gaps</td></tr></tbody></table><h2 id="current-finding-status" tabindex="-1">Current finding status <a class="header-anchor" href="#current-finding-status" aria-label="Permalink to “Current finding status”">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Findings</th><th>Disposition</th></tr></thead><tbody><tr><td><strong>Completed on dev</strong></td><td>SEC-01, FIN-01/02, ENG-05, DEPLOY-01, UI-01/02/03, DATA-01/04, FIN-03, PRIV-01/02</td><td>Merged through PRs #75, #80 and #81. Rendered accessibility QA remains separate.</td></tr><tr><td><strong>Implemented on follow-up branch</strong></td><td>ENG-01/02/03/04, SEARCH-01 calibration, QA-01 browser suite</td><td>Full workflow <a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42574353592" target="_blank" rel="noreferrer">42574353592</a> passed: Node tests, syntax checks, production/dev builds, all six Chromium browser tests, documentation-preservation build and workflow YAML parsing.</td></tr><tr><td><strong>Partial / ongoing control</strong></td><td>SEARCH-03, QA-REP-01</td><td>Strict/deferred outflow parity exists across four strategies, but booking/maturity/payout/fee/reserved-liquidity parity remains. Automated report semantic, mobile and print smoke assertions pass; offline/chart checks and manual accessibility/print QA remain.</td></tr><tr><td><strong>Metadata contract implemented; data review pending</strong></td><td>DATA-06</td><td>Source review, economic update and schema version are separate. All 29 bank review/update dates remain blank pending real source checks.</td></tr><tr><td><strong>Research / documented limitation</strong></td><td>DATA-03, DATA-05</td><td>Special-product constraints remain inactive; transfer fees remain deliberately simplified.</td></tr><tr><td><strong>Open hosting verification</strong></td><td>WEB-SEC-02</td><td>GitHub Pages retained by owner decision; actual production/dev response headers remain to be checked.</td></tr><tr><td><strong>Deferred architecture</strong></td><td>SEARCH-02</td><td>Staged decomposition plan only; no broad refactor before parity baselines.</td></tr><tr><td><strong>Scope closed</strong></td><td>DATA-02</td><td>Age-segment controls are candidate filters, not eligibility verification.</td></tr></tbody></table><h2 id="method-and-verification-boundary" tabindex="-1">Method and verification boundary <a class="header-anchor" href="#method-and-verification-boundary" aria-label="Permalink to “Method and verification boundary”">​</a></h2><p>The review applies the <a href="https://github.com/aaron-fredrick/RULESETS/tree/main/Coding" target="_blank" rel="noreferrer">Coding</a>, <a href="https://github.com/aaron-fredrick/RULESETS/tree/main/UI" target="_blank" rel="noreferrer">UI</a> and <a href="https://github.com/aaron-fredrick/RULESETS/tree/main/Web" target="_blank" rel="noreferrer">Web</a> rulesets. It is a risk-based source audit of the active engine, strategy/search paths, browser UI, reporting, catalogue/configuration paths, CLI, build scripts, Pages workflows and tests. It is not a line-by-line proof, formal verification, financial-product certification, penetration test, legal opinion or complete external revalidation of every bank rate and fee.</p><p>The latest completed workflow is <a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42574353592" target="_blank" rel="noreferrer">42574353592</a>, which passed Node tests, syntax checks, production/dev builds, all six Chromium browser tests, the documentation-preservation build and workflow YAML parsing. The report checks now pass for semantic column headers, 320px document overflow and print table width. Earlier failures exposed missing ledger header scopes and mobile navigation overflow; fixes are included in the current branch. Earlier passing workflows predate these report assertions and do not establish current green status.</p><p>Static inspection and automated smoke tests do not establish screen-reader output, full WCAG conformance, real-device behaviour, actual printed/PDF pagination, live bank rates or deployed HTTP response headers.</p><h2 id="remaining-work" tabindex="-1">Remaining work <a class="header-anchor" href="#remaining-work" aria-label="Permalink to “Remaining work”">​</a></h2><ol><li>Extend report QA beyond the passing smoke suite: verify offline behaviour, chart initialization, large ledgers, print/PDF pagination and manual accessibility.</li><li>Expand cross-strategy parity to eligible bookings, maturity/installment payouts, fees and reserved liquidity.</li><li>Complete offline/chart report checks and manual print, keyboard, screen-reader, contrast and 200–400% zoom review.</li><li>Recheck bank sources and populate only defensible review/update dates.</li><li>Verify actual production and dev response headers.</li><li>Keep SEARCH-02 refactoring, special-product activation, transfer-channel modelling and main-branch preview integration deferred.</li></ol><p>See the <a href="./IMPLEMENTATION-PLAN.html">implementation plan</a> for detailed acceptance gates.</p><h2 id="crawler-and-release-path-policy" tabindex="-1">Crawler and release-path policy <a class="header-anchor" href="#crawler-and-release-path-policy" aria-label="Permalink to “Crawler and release-path policy”">​</a></h2><p>The <code>/dev/</code> subtree is a public preview, not an indexable production destination. The root <code>robots.txt</code> permits crawlers to fetch preview pages so they can observe <code>noindex,nofollow</code>; every generated dev HTML entry point must carry that directive; and the production sitemap must contain only canonical production URLs, never preview URLs. <code>robots.txt</code> is crawler guidance, not access control. Production docs output merges canonical root and <code>/web/</code> URLs into the sitemap. Preview builds omit sitemap output and mark dev HTML noindex. This is a verified positive control, not an open finding.</p>`,16)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};